begin;
select plan(34);
select has_table('public','proposal_delivery_links','delivery links exist');
select has_table('public','proposal_events','commercial events exist');
select has_table('public','proposal_decisions','decisions exist');
select has_column('public','proposals','sent_version_id','sent version is explicit');
select has_column('public','proposals','accepted_version_id','accepted version is explicit');
select has_function('public','prepare_proposal_delivery',array['uuid','text','timestamp with time zone','text','text'],'prepare RPC exists');
select has_function('public','activate_proposal_delivery',array['uuid','boolean'],'activation RPC exists');
select has_function('public','revoke_proposal_delivery',array['uuid'],'revocation RPC exists');
select has_function('public','get_public_proposal',array['text','boolean'],'public resolver exists');
select has_function('public','decide_public_proposal',array['text','text','text','text','text'],'decision RPC exists');
select ok((select relrowsecurity from pg_class where oid='public.proposal_delivery_links'::regclass),'delivery RLS enabled');
select ok((select relrowsecurity from pg_class where oid='public.proposal_events'::regclass),'events RLS enabled');
select ok((select relrowsecurity from pg_class where oid='public.proposal_decisions'::regclass),'decisions RLS enabled');
select ok(not has_table_privilege('anon','public.proposal_delivery_links','SELECT'),'anon cannot enumerate links');
select ok(not has_table_privilege('anon','public.proposal_events','SELECT'),'anon cannot enumerate events');
select ok(not has_table_privilege('anon','public.proposal_decisions','SELECT'),'anon cannot enumerate decisions');
select ok(has_function_privilege('anon','public.get_public_proposal(text,boolean)','EXECUTE'),'anon resolves opaque token');
select ok(has_function_privilege('anon','public.decide_public_proposal(text,text,text,text,text)','EXECUTE'),'anon submits controlled decision');
select ok(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in('prepare_proposal_delivery','activate_proposal_delivery','revoke_proposal_delivery','get_public_proposal','decide_public_proposal') and p.prosecdef and not ('search_path=""'=any(coalesce(p.proconfig,array[]::text[])))),'D5 definers have safe search path');

insert into public.organizations(id,name,slug) values('80000000-0000-4000-8000-000000000001','D5 Test','d5-test');
insert into auth.users(id,email,created_at,updated_at) values('80000000-0000-4000-8000-000000000011','writer@example.invalid',now(),now());
insert into public.organization_members(id,organization_id,user_id,status) values('80000000-0000-4000-8000-000000000021','80000000-0000-4000-8000-000000000001','80000000-0000-4000-8000-000000000011','active');
insert into public.organization_member_roles(organization_id,membership_id,role_id) select m.organization_id,m.id,r.id from public.organization_members m join public.roles r on r.organization_id=m.organization_id and r.slug='colaborador' where m.id='80000000-0000-4000-8000-000000000021';
insert into public.leads(id,organization_id,full_name,email,service_interest,message,source,landing_path,status,consent_version) values('80000000-0000-4000-8000-000000000041','80000000-0000-4000-8000-000000000001','Cliente Teste','cliente@example.invalid','other','Mensagem inteiramente ficticia.','outbound','/crm/manual','new','manual');
insert into public.opportunities(id,organization_id,lead_id,stage_id,title,created_by,updated_by) select '80000000-0000-4000-8000-000000000051','80000000-0000-4000-8000-000000000001','80000000-0000-4000-8000-000000000041',id,'Oportunidade D5','80000000-0000-4000-8000-000000000011','80000000-0000-4000-8000-000000000011' from public.pipeline_stages where organization_id='80000000-0000-4000-8000-000000000001' and position=1;
insert into public.clients(id,organization_id,source_lead_id,source_opportunity_id,created_by) values('80000000-0000-4000-8000-000000000061','80000000-0000-4000-8000-000000000001','80000000-0000-4000-8000-000000000041','80000000-0000-4000-8000-000000000051','80000000-0000-4000-8000-000000000011');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"80000000-0000-4000-8000-000000000011","role":"authenticated","aal":"aal2"}',true);
select public.create_proposal('80000000-0000-4000-8000-000000000061',null,'Proposta D5',current_date+30);
select public.create_proposal_version((select id from public.proposals),'80000000-0000-4000-8000-000000000071');
select lives_ok($$select public.prepare_proposal_delivery((select id from public.proposal_versions),repeat('a',64),now()+interval '30 days',null,null)$$,'writer prepares delivery');
set local role anon;
select is(public.get_public_proposal(repeat('a',64),false),null,'pending link is private');
set local role authenticated; select set_config('request.jwt.claims','{"sub":"80000000-0000-4000-8000-000000000011","role":"authenticated","aal":"aal2"}',true);
select lives_ok($$select public.activate_proposal_delivery((select id from public.proposal_delivery_links),false)$$,'writer activates delivery');
select is((select status::text from public.proposals),'sent','activation marks sent');
set local role anon;
select isnt(public.get_public_proposal(repeat('a',64),false),null,'active token resolves');
select public.get_public_proposal(repeat('a',64),true);
reset role;
select is((select count(*)::integer from public.proposal_events where event_type='viewed'),1,'first view is recorded');
set local role anon;
select public.get_public_proposal(repeat('a',64),true);
reset role;
select is((select count(*)::integer from public.proposal_events where event_type='viewed'),1,'repeat view is minimized');
set local role anon;
select is(public.decide_public_proposal(repeat('a',64),'accepted','Responsavel Ficticio','responsavel@example.invalid',null),'accepted','acceptance succeeds');
reset role;
select is((select status::text from public.proposals),'accepted','proposal reaches accepted');
select is((select accepted_version_id from public.proposals),(select id from public.proposal_versions),'accepted version is exact');
set local role anon;
select is(public.decide_public_proposal(repeat('a',64),'accepted','Responsavel Ficticio',null,null),'accepted','acceptance replay is idempotent');
select throws_ok($$select public.decide_public_proposal(repeat('a',64),'rejected','Responsavel Ficticio',null,null)$$,'P0001','Decision is final.','conflicting decision is blocked');
set local role authenticated; select set_config('request.jwt.claims','{"sub":"80000000-0000-4000-8000-000000000011","role":"authenticated","aal":"aal2"}',true);
select lives_ok($$select public.revoke_proposal_delivery((select id from public.proposal_delivery_links))$$,'writer revokes link');
set local role anon;
select is(public.get_public_proposal(repeat('a',64),false),null,'revoked token is generic');
reset role;
select throws_ok($$insert into public.proposal_delivery_links(organization_id,proposal_id,proposal_version_id,token_hash,expires_at,created_by) select organization_id,proposal_id,id,'raw-token',now()+interval '1 day',created_by from public.proposal_versions$$,'23514',null,'raw or malformed token cannot be stored');
select * from finish(); rollback;
